import {VERSION,escapeHtml as h,parseHar,inspectEvents,compare,specFromRows,specFromJSON,parseCSV,csv,reportData,bugMarkdown} from './core.mjs';
import {readXLSX,writeXLSX} from './sheets.mjs';
import {demoData} from './demo.mjs';

const paths={
 grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
 pulse:'<path d="M2 12h5l3-7 4 14 3-7h5"/>',layers:'<path d="m12 3 10 6-10 6L2 9l10-6Z"/><path d="m2 13 10 6 10-6M2 17l10 6 10-6"/>',
 report:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8M8 17h5"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 4.2 2c-1 .7-1.7 1-1.7 2.5M12 17h.01"/>',
 upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v4a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-4"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 16v3a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-3"/>',
 code:'<path d="m8 7-5 5 5 5m8-10 5 5-5 5m-3-13-2 20"/>',sheet:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M4 9h16M4 15h16M10 9v12"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',play:'<path d="m8 4 13 8-13 8V4Z"/>',
 shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8.5 12 2.5 2.5 4.5-5"/>',check:'<path d="m5 12 4 4L19 6"/>',alert:'<path d="M10.2 4a2 2 0 0 1 3.6 0l8 14a2 2 0 0 1-1.8 3H4a2 2 0 0 1-1.8-3l8-14Z"/><path d="M12 9v4m0 4h.01"/>',
 search:'<circle cx="10.5" cy="10.5" r="7"/><path d="m16 16 5 5"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',folder:'<path d="M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7Z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>'
};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]??paths.report}</svg>`;
const views={overview:['Tổng quan','grid'],events:['Sự kiện','pulse'],comparison:['Đối chiếu đặc tả','layers'],reports:['Báo cáo','report'],guide:['Hướng dẫn','help']};
const state={view:'overview',files:[],events:[],specs:[],specFile:'',specWarnings:[],workbook:null,sheet:'',rows:[],demo:false,busy:false,analyzed:false,search:'',vendor:'ALL',eventFilter:'ALL',resultFilter:'ALL',page:1,selected:null};
const $=s=>document.querySelector(s),num=n=>Number(n).toLocaleString('vi-VN');
const labels={PASS:'Khớp',FAIL:'Sai lệch',REVIEW:'Cần xem lại',MISSING:'Chưa thấy',EXTRA:'Ngoài đặc tả',IGNORE:'Bỏ qua'};
const badge=(status,label)=>`<span class="status ${String(status).toLowerCase()}">${h(label??labels[status]??status)}</span>`;
const vendorTag=v=>`<span class="vendor-tag ${String(v).toLowerCase()}">${h(v==='ANY'?'TẤT CẢ':v)}</span>`;
const time=s=>{if(!s||!Number.isFinite(Date.parse(s)))return'—';return new Intl.DateTimeFormat('vi-VN',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date(s));};
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4200);}
function navigate(view){if(!views[view])return;state.view=view;state.page=1;state.search='';state.vendor='ALL';history.replaceState(null,'','#'+view);render();window.scrollTo({top:0,behavior:'smooth'});}
function refreshData(){state.events=inspectEvents(state.files.flatMap(f=>f.events).sort((a,b)=>a.timestamp-b.timestamp));state.rows=state.analyzed?compare(state.events,state.specs):[];}
function navigation(){ $('#navigation').innerHTML=Object.entries(views).map(([key,[title,symbol]])=>`<button data-view="${key}" class="nav-link ${state.view===key?'active':''}" title="${title}" ${state.view===key?'aria-current="page"':''}>${icon(symbol)}<span class="nav-label">${title}</span>${key==='events'&&state.events.length?`<span class="nav-count">${num(state.events.length)}</span>`:''}</button>`).join('');$('#breadcrumb-title').textContent=views[state.view][0]; }
function heading(title,description,actions=''){return`<div class="page-heading"><div><div class="eyebrow">EVENT TRACKING / WEB EDITION</div><h1>${title}</h1><p>${description}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function demoBanner(){return state.demo?`<div class="mode-banner">${icon('info')}<span><strong>Dữ liệu minh họa.</strong> Các kết quả dưới đây được tạo để bạn thử tính năng, không phải dữ liệu website thật.</span><button data-action="reset">Thoát demo</button></div>`:'';}
function stats(){const matched=state.rows.filter(r=>r.status==='PASS').length,failures=state.rows.filter(r=>r.status==='FAIL').length;return`<div class="stat-grid">${[
 ['Event đã ghi nhận',state.events.length,'event',`${state.files.length} file HAR đã nhập`,'pulse'],
 ['Event trong đặc tả',state.specs.reduce((s,x)=>s+x.rules.length,0),'rule',state.specFile?'Đã nạp đặc tả':'Chưa có file đặc tả','layers'],
 ['Kết quả khớp',matched,'rule',state.analyzed?'Theo phạm vi đã đối chiếu':'Chờ chạy đối chiếu','check'],
 ['Sai lệch cần kiểm tra',failures,'rule',state.analyzed?`${state.rows.filter(r=>r.status==='MISSING').length} rule chưa thấy event`:'Chờ chạy đối chiếu','alert']
 ].map(([title,value,unit,foot,symbol])=>`<div class="stat-card"><div class="stat-top"><span>${title}</span><span class="stat-icon">${icon(symbol)}</span></div><div class="stat-value">${num(value)}<span>${unit}</span></div><div class="stat-foot"><i class="dot"></i>${h(foot)}</div></div>`).join('')}</div>`;}
function fileCard(kind){const isHar=kind==='har';const has=isHar?state.files.length:state.specs.length;return`<section class="upload-card"><div class="upload-top"><span class="step-number">${isHar?'01':'02'}</span><strong>${isHar?'Dữ liệu thực tế':'Đặc tả kỳ vọng'}</strong><span class="${isHar?'required':'optional'}">${isHar?'BẮT BUỘC':'KHÔNG BẮT BUỘC'}</span></div><div class="dropzone ${has?'has-file':''}" tabindex="0" role="button" data-drop="${kind}" aria-label="${isHar?'Chọn file HAR':'Chọn file đặc tả'}"><span class="drop-icon">${icon(isHar?'upload':'sheet')}</span>${has?`<span class="file-name">${h(isHar?`${state.files.length} file HAR · ${num(state.events.length)} event`:state.specFile)}</span><span class="file-meta">${isHar?'Chọn thêm hoặc kéo thả file HAR khác':`${num(state.specs.length)} dòng đặc tả · Bấm để thay file`}</span>`:`<strong>Kéo thả file hoặc <b>chọn từ máy tính</b></strong><p>${isHar?'HAR từ Chrome / Edge · Tối đa 60 MB / file':'Excel (.xlsx), CSV hoặc JSON · Tối đa 20 MB'}</p>`}</div>${isHar&&state.files.length?`<div class="file-list">${state.files.map((f,i)=>`<span class="file-chip">${icon('report').replace('<svg','<svg style="width:10px;height:10px"')} ${h(f.name)}<button data-remove="${i}" aria-label="Xóa file ${h(f.name)}">×</button></span>`).join('')}</div>`:''}${!isHar&&state.workbook?`<label class="sheet-select">Sheet <select id="sheet-select">${state.workbook.names.map(n=>`<option ${n===state.sheet?'selected':''}>${h(n)}</option>`).join('')}</select></label>`:''}${!isHar&&has?`<div class="file-list"><span class="file-chip">${num(state.specs.length)} dòng<button data-action="remove-spec" aria-label="Xóa đặc tả">×</button></span></div>`:''}<div class="upload-foot">${icon(isHar?'globe':'layers')}${isHar?'Thu thập request bằng Network → Export HAR (sanitized)':'Hỗ trợ cột Event Name, Nền tảng, Luồng, DataLayer Sample'}</div></section>`;}
function warnings(){const list=[...state.specWarnings,...state.files.flatMap(x=>x.warnings)];return list.length?`<div class="notice warning">${icon('alert')} <strong>${num(list.length)} lưu ý khi đọc dữ liệu</strong><ul>${list.slice(0,3).map(x=>`<li>${h(x)}</li>`).join('')}</ul>${list.length>3?`<button class="button text small" data-action="warnings">Xem tất cả lưu ý</button>`:''}</div>`:'';}
function empty(title,description,symbol='pulse',action=''){return`<div class="empty-state"><span class="empty-art">${icon(symbol)}</span><h3>${title}</h3><p>${description}</p>${action}</div>`;}
function overview(){return heading('Không gian kiểm thử','Nhập dữ liệu, đối chiếu event và tìm sai lệch trong cùng một nơi.',`<button class="button" data-action="demo">${icon('play')} Thử dữ liệu mẫu</button><button class="button primary" data-view="guide">${icon('help')} Hướng dẫn</button>`)+demoBanner()+
 `<section class="hero"><div class="hero-content"><div class="hero-label"><span></span> GA4 · INSIDER · NETWORK EVENTS</div><h2>Từ request đến kết quả kiểm thử.</h2><p>Kiểm tra event tracking ngay trên trình duyệt.<br>Không cài Node. Không extension. Chủ động dữ liệu.</p></div><div class="hero-art" aria-hidden="true"><div class="flow-card"><div class="flow-card-top">EVENT RECEIVED <span>DECODED</span></div><div class="code-row">{<br>&nbsp; <b>"event"</b>: <em>"search_submit"</em>,<br>&nbsp; <b>"service"</b>: <em>"hotel"</em>,<br>&nbsp; <b>"source"</b>: <em>"GA4"</em><br>}</div></div><div class="check-bubble">${icon('check')} Ready to validate</div></div></section>`+stats()+
 `<div class="section-header"><div><h2>Bắt đầu phiên kiểm thử</h2><p>Chọn dữ liệu thực tế và đặc tả bạn muốn kiểm tra.</p></div><span class="tag">2 BƯỚC ĐƠN GIẢN</span></div><div class="upload-grid">${fileCard('har')}${fileCard('spec')}</div><div class="import-bottom"><div class="inline-note">${icon('shield')} File được xử lý tại trình duyệt. Tải lại trang sẽ xóa phiên hiện tại.</div><button class="button primary ${state.busy?'pulse':''}" data-action="analyze" ${!state.events.length||state.busy?'disabled':''}>${state.busy?'Đang đọc dữ liệu…':'Bắt đầu kiểm tra'} ${icon('arrow')}</button></div>${warnings()}`+
 `<section class="panel"><div class="panel-head"><div><h2>Sự kiện gần đây</h2><p>${state.events.length?'Những event mới nhất trong dữ liệu đã nhập.':'Event sẽ xuất hiện sau khi bạn nhập file HAR.'}</p></div><button class="button text small" data-view="events">Xem tất cả ${icon('arrow')}</button></div>${state.events.length?eventTable(state.events.slice(-5).reverse(),false):empty('Chưa có dữ liệu để hiển thị','Nhập file HAR để xem event thực tế hoặc dùng dữ liệu mẫu để làm quen với công cụ.','pulse')}</section>`;
}
function eventTable(events,withPagination=true){return`<div class="table-wrap"><table><thead><tr><th>EVENT NAME</th><th>NỀN TẢNG</th><th>THỜI GIAN</th><th>HTTP</th><th>KIỂM TRA</th><th></th></tr></thead><tbody>${events.map(e=>`<tr data-event="${h(e.id)}" tabindex="0" role="button" aria-label="Xem event ${h(e.name)}"><td><div class="event-name"><i class="event-bullet"></i>${h(e.name)}</div><div class="event-sub">${h(e.endpoint)}</div></td><td>${vendorTag(e.vendor)}</td><td class="mono">${time(e.time)}</td><td>${badge(e.status>0&&e.status<400?'PASS':'FAIL',e.status||'Lỗi mạng')}</td><td>${e.issues.some(x=>x.code==='HTTP_ERROR')?badge('FAIL','Request lỗi'):e.issues.length?badge('REVIEW','Cần xem lại'):badge('PASS','Đã đọc')}</td><td class="right"><button class="row-action" data-event="${h(e.id)}" aria-label="Xem chi tiết ${h(e.name)}">${icon('eye')}</button></td></tr>`).join('')}</tbody></table></div>`;}
function pagination(total){const pages=Math.max(1,Math.ceil(total/25));return`<div class="table-bottom"><span>${total?`${num((state.page-1)*25+1)}–${num(Math.min(state.page*25,total))} / ${num(total)} dòng`:'0 dòng'}</span><div class="pagination"><button data-page="${state.page-1}" ${state.page<=1?'disabled':''} aria-label="Trang trước">‹</button><span>${state.page} / ${pages}</span><button data-page="${state.page+1}" ${state.page>=pages?'disabled':''} aria-label="Trang sau">›</button></div></div>`;}
function searchBox(placeholder){return`<label class="searchbox">${icon('search')}<input id="table-search" type="search" placeholder="${placeholder}" value="${h(state.search)}" aria-label="Tìm kiếm"></label>`;}
function vendorSelect(){const vendors=[...new Set(state.events.map(e=>e.vendor))];return`<select id="vendor-filter" aria-label="Lọc nền tảng"><option value="ALL">Tất cả nền tảng</option>${vendors.map(v=>`<option value="${h(v)}" ${state.vendor===v?'selected':''}>${h(v)}</option>`).join('')}</select>`;}
function filteredEvents(){return state.events.filter(e=>(state.vendor==='ALL'||e.vendor===state.vendor)&&(state.eventFilter==='ALL'||state.eventFilter==='ERROR'&&(e.status===0||e.status>=400)||state.eventFilter==='DUPLICATE'&&e.issues.some(x=>x.code==='POSSIBLE_DUPLICATE')||state.eventFilter==='UNPARSED'&&!e.decoded)&&`${e.name} ${e.endpoint} ${e.page} ${JSON.stringify(e.payload)}`.toLowerCase().includes(state.search.toLowerCase()));}
function eventsView(){const items=filteredEvents();const requests=state.files.reduce((s,f)=>s+f.requests,0),ignored=state.files.reduce((s,f)=>s+f.ignored,0);return heading('Khám phá sự kiện',`${num(state.events.length)} event từ ${num(requests)} request · ${num(ignored)} request không phải tracking được bỏ qua.`,`<button class="button" data-action="import-har">${icon('upload')} Nhập thêm HAR</button><button class="button primary" data-export="events-csv" ${!state.events.length?'disabled':''}>${icon('download')} Xuất CSV</button>`)+demoBanner()+
 `<div class="filter-tabs">${[['ALL','Tất cả',state.events.length],['ERROR','Request lỗi',state.events.filter(e=>e.status===0||e.status>=400).length],['DUPLICATE','Có thể bắn trùng',state.events.filter(e=>e.issues.some(x=>x.code==='POSSIBLE_DUPLICATE')).length],['UNPARSED','Chưa giải mã',state.events.filter(e=>!e.decoded).length]].map(([value,title,count])=>`<button class="filter-tab ${state.eventFilter===value?'active':''}" data-event-filter="${value}">${title}<span>${num(count)}</span></button>`).join('')}</div><div class="panel"><div class="toolbar">${searchBox('Tìm tên event, endpoint, tham số…')}<div class="filters">${vendorSelect()}<span style="font-size:9px;color:#9ba8bb">Theo thời gian trong HAR</span></div></div>${items.length?eventTable(items.slice((state.page-1)*25,state.page*25)):empty(state.events.length?'Không có event phù hợp':'Chưa có dữ liệu HAR',state.events.length?'Thử thay bộ lọc hoặc từ khóa tìm kiếm.':'Nhập file HAR ở Tổng quan để xem request tracking.','search')} ${pagination(items.length)}</div><div class="notice">${icon('info')} Event ở đây được trích từ request mạng. DataLayer / InsiderQueue và trạng thái tiếp nhận tại vendor không được xác nhận chỉ bằng HAR.</div>`;}
function comparisonView(){
 if(!state.analyzed)return heading('Đối chiếu đặc tả','Kiểm tra dữ liệu thực tế so với yêu cầu tracking.')+`<div class="panel">${empty('Chưa chạy đối chiếu','Chọn HAR và đặc tả ở Tổng quan, sau đó bấm Bắt đầu kiểm tra.','layers',`<button class="button primary" data-view="overview">Về Tổng quan ${icon('arrow')}</button>`)}</div>`;
 if(!state.specs.length)return heading('Đối chiếu đặc tả','Thêm file đặc tả để kiểm tra tên event và các tham số.')+`<div class="panel">${empty('Chưa có đặc tả kỳ vọng',`Đã đọc ${num(state.events.length)} event. Bạn vẫn có thể xem và xuất event; cần thêm đặc tả để kết luận khớp hay sai lệch.`,'sheet',`<button class="button primary" data-view="overview">Thêm file đặc tả ${icon('arrow')}</button>`)}</div>`;
 const expected=state.rows.filter(r=>r.status!=='EXTRA'),matched=expected.filter(r=>r.status==='PASS').length,pct=expected.length?Math.round(matched/expected.length*100):0;
 const rows=state.rows.filter(r=>(state.resultFilter==='ALL'||r.status===state.resultFilter)&&`${r.name} ${r.flow} ${r.vendor} ${r.issues.join(' ')}`.toLowerCase().includes(state.search.toLowerCase()));
 return heading('Đối chiếu đặc tả',`Đối chiếu với ${h(state.specFile)}${state.sheet?' · '+h(state.sheet):''}`,`<button class="button" data-action="analyze">${icon('layers')} Kiểm tra lại</button><button class="button primary" data-view="reports">${icon('download')} Xuất báo cáo</button>`)+demoBanner()+
 `<div class="panel summary-panel"><div class="result-summary"><div class="donut" style="--pct:${pct}%"><div>${pct}%<small>RULE KHỚP</small></div></div><div><h3>${num(matched)} / ${num(expected.length)} rule khớp trong phạm vi kiểm tra</h3><p>“Chưa thấy” nghĩa là chưa có trong HAR. Chỉ xác nhận lỗi thiếu event sau khi đã thực hiện đúng luồng.</p><div class="summary-tags">${badge('FAIL',`${expected.filter(x=>x.status==='FAIL').length} sai lệch`)}${badge('MISSING',`${expected.filter(x=>x.status==='MISSING').length} chưa thấy`)}${badge('REVIEW',`${expected.filter(x=>x.status==='REVIEW').length} cần xem lại`)}</div></div></div></div>`+
 (state.specs.some(s=>s.inferred)?`<div class="notice">${icon('info')} <strong>Đặc tả từ sample:</strong> kiểm tra tên event, sự hiện diện và kiểu dữ liệu. Giá trị ví dụ trong Excel không tự trở thành giá trị bắt buộc. “Khớp” không xác nhận toàn bộ điều kiện nghiệp vụ.</div>`:'')+
 `<div class="filter-tabs">${[['ALL','Tất cả'],...Object.entries(labels).filter(([s])=>s!=='IGNORE')].map(([value,title])=>`<button class="filter-tab ${state.resultFilter===value?'active':''}" data-result-filter="${value}">${title}<span>${num(value==='ALL'?state.rows.length:state.rows.filter(r=>r.status===value).length)}</span></button>`).join('')}</div><div class="panel"><div class="toolbar">${searchBox('Tìm event, luồng hoặc sai lệch…')}<span style="font-size:10px;color:#93a2b7">Bấm vào dòng để xem bằng chứng</span></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>EVENT / ĐẶC TẢ</th><th>NỀN TẢNG</th><th>LUỒNG</th><th>ĐÃ THẤY</th><th>KẾT QUẢ</th><th></th></tr></thead><tbody>${rows.slice((state.page-1)*25,state.page*25).map(r=>`<tr data-comparison="${h(r.id)}" tabindex="0" role="button" aria-label="Chi tiết đối chiếu ${h(r.name)}"><td><div class="event-name">${h(r.name)}</div><div class="event-sub">${r.spec?`${h(r.spec.provenance.file)} · dòng ${r.spec.provenance.row}`:'Không có trong đặc tả'}</div></td><td>${vendorTag(r.vendor)}</td><td>${h(r.flow||'—')}</td><td class="mono">${r.matches}</td><td>${badge(r.status)}</td><td class="right">${icon('eye')}</td></tr>`).join('')}</tbody></table></div>`:empty('Không có kết quả phù hợp','Thử thay bộ lọc hoặc từ khóa.','search')}${pagination(rows.length)}</div>`;
}
function reportsView(){return heading('Báo cáo kiểm thử','Mang kết quả, payload và bằng chứng sang công cụ làm việc của bạn.',`<button class="button" data-action="reset">${icon('trash')} Xóa phiên</button>`)+demoBanner()+stats()+(!state.events.length?`<div class="panel">${empty('Chưa có dữ liệu để xuất','Nhập HAR ở Tổng quan hoặc thử dữ liệu mẫu.','report',`<button class="button primary" data-view="overview">Về Tổng quan ${icon('arrow')}</button>`)}</div>`:
 `<div class="report-grid">${[
 ['xlsx','sheet','Báo cáo Excel','Tổng quan, toàn bộ event, kết quả đối chiếu và danh sách sai lệch trong một workbook.','XLSX · 4 SHEETS','Tải báo cáo Excel'],
 ['json','code','Dữ liệu & bằng chứng','Event đã chuẩn hóa, HTTP status, payload đã che trường nhạy cảm và kết quả kiểm tra.','JSON · STRUCTURED','Tải dữ liệu JSON'],
 ['html','report','Báo cáo dễ chia sẻ','Một file HTML độc lập để mở trong trình duyệt, xem kết quả và bằng chứng.','HTML · STANDALONE','Tải báo cáo HTML'],
 ['bugs','alert','Danh sách sai lệch','Mỗi rule sai lệch có mô tả, dòng đặc tả và evidence ID để bạn đưa lên task.','MARKDOWN · FAIL ONLY','Tải danh sách lỗi'],
 ['events-csv','pulse','Danh sách event','Bảng event với thời gian, nền tảng, endpoint, HTTP status và payload.','CSV · UTF-8','Tải event CSV'],
 ['results-csv','layers','Kết quả đối chiếu','Các trạng thái khớp, sai lệch, cần xem lại, chưa thấy và ngoài đặc tả.','CSV · UTF-8','Tải đối chiếu CSV']
 ].map(([format,symbol,title,description,meta,label])=>`<section class="report-card"><div class="report-icon">${icon(symbol)}</div><div><h3>${title}</h3><p>${description}</p><div class="report-format">${meta}</div></div><button class="button" data-export="${format}" ${['bugs','results-csv'].includes(format)&&!state.analyzed?'disabled':''}>${icon('download')}${label}</button></section>`).join('')}</div><div class="notice">${icon('shield')} Báo cáo bỏ qua request headers/cookies và che một số trường như token, email, phone, user ID. Việc che tự động không bảo đảm loại hết dữ liệu nhạy cảm; hãy xem lại trước khi chia sẻ.</div>`);}
function guideView(){return heading('Bắt đầu trong vài phút','Dùng trình duyệt hiện có, không cần Node hay extension.',`<button class="button soft" data-action="demo">${icon('play')} Thử dữ liệu mẫu</button>`)+
 `<div class="guide-grid"><section class="panel guide-card"><h2>01 · Lấy dữ liệu từ website</h2><ol class="guide-steps"><li>Mở website cần test trên <strong>Chrome hoặc Edge</strong>.</li><li>Bấm <strong>F12</strong> hoặc <strong>Ctrl + Shift + I</strong>, chọn tab <strong>Network</strong>.</li><li>Bật <strong>Preserve log</strong>. Xóa request cũ rồi thực hiện luồng cần kiểm tra. Chờ tracking gửi xong.</li><li>Chọn <strong>Export HAR (sanitized)</strong> để tải file <code>.har</code>. Không cần bật xuất dữ liệu nhạy cảm.</li><li>Về <strong>Tổng quan</strong>, chọn HAR, thêm đặc tả nếu có và bấm <strong>Bắt đầu kiểm tra</strong>.</li></ol><div class="guide-links"><a href="https://developer.chrome.com/docs/devtools/network/reference/#save-as-har" target="_blank" rel="noreferrer">Hướng dẫn Chrome ↗</a><a href="https://learn.microsoft.com/en-us/microsoft-edge/devtools/network/reference" target="_blank" rel="noreferrer">Hướng dẫn Edge ↗</a></div></section>
 <section class="panel guide-card"><h2>02 · Chuẩn bị đặc tả</h2><p>Chọn <strong>Excel (.xlsx)</strong> có cột <code>Event Name</code>. Công cụ tự tìm header trong 60 dòng đầu và ưu tiên sheet <code>Tổng hợp Event tracking</code>.</p><p>Cột hỗ trợ: <code>Nền tảng</code>, <code>Luồng</code>, <code>Event Description</code>, <code>DataLayer Sample</code>, <code>Note</code>. Bạn có thể chọn lại sheet sau khi nhập.</p><p>Sample trong Excel dùng để kiểm tra <strong>sự hiện diện và kiểu dữ liệu</strong>. Giá trị ví dụ có thể thay đổi theo thao tác; không tự coi chúng là hằng số.</p><p>Muốn so sánh giá trị chính xác, dùng <strong>JSON rule</strong> với <code>eq</code>. Bản web hỗ trợ <code>exists</code>, <code>not_exists</code>, <code>type</code>, <code>one_of</code>, <code>range</code>, <code>subset</code>, <code>ignore</code>. <code>regex</code>, <code>ref</code>, thứ tự và thời gian theo bước được chuyển sang “Cần xem lại”.</p><div class="template-section"><button class="button" data-export="template-xlsx">${icon('download')} Excel mẫu</button> <button class="button" data-export="template-json">${icon('download')} JSON rule mẫu</button></div></section>
 <section class="panel guide-card full"><h2>Phạm vi của bản web</h2><div class="scope-grid"><div class="scope-item"><strong>Có thể làm ngay</strong>Đọc HAR, giải mã GA4 (query/form/batch), Insider JSON/base64 và payload JSON phổ biến. Lọc event, xem HTTP lỗi, đánh dấu nghi ngờ trùng, đối chiếu đặc tả và xuất XLSX/HTML/JSON/CSV.</div><div class="scope-item"><strong>Cần hiểu khi đọc kết quả</strong>Trang web này phân tích file đã ghi. Nó không theo dõi tab khác, không mở Chrome trên máy bạn, không quan sát trực tiếp dataLayer/InsiderQueue và không xác nhận vendor ingestion. Payload mã hóa hoặc không hỗ trợ cần kiểm tra thủ công.</div></div><div class="spacer"></div><div class="section-header"><h2>Ý nghĩa các trạng thái</h2></div><div class="table-wrap"><table><tbody><tr><td>${badge('PASS')}</td><td>Các phép kiểm được hỗ trợ đã đạt; với sample Excel, đây là khớp cấu trúc.</td></tr><tr><td>${badge('FAIL')}</td><td>Thiếu trường, sai kiểu/giá trị, sai số lần hoặc request bị HTTP lỗi.</td></tr><tr><td>${badge('MISSING')}</td><td>Chưa thấy trong HAR. Cần xác nhận đã chạy luồng trước khi báo bug.</td></tr><tr><td>${badge('REVIEW')}</td><td>Sample chưa đọc được, thiếu context, rule chưa duyệt hoặc không đủ bằng chứng.</td></tr><tr><td>${badge('EXTRA')}</td><td>Event thực tế chưa có dòng tương ứng trong đặc tả đã nhập.</td></tr></tbody></table></div></section>
 <section class="panel guide-card full"><h2>Đưa lên hosting của bạn</h2><p>Đây là website tĩnh, không có backend hay API key. Đưa toàn bộ thư mục <code>dist/</code> lên hosting tĩnh. Trong repository này, bản web ở thư mục <code>web/</code>. Với Render, tạo <strong>Static Site</strong>, đặt Root Directory <code>web</code>, Publish Directory <code>dist</code>, Build Command <code>echo ready</code> và biến <code>SKIP_INSTALL_DEPS=true</code>. Hoặc dùng <code>render.yaml</code> ở gốc repo qua New → Blueprint.</p><p>Phiên làm việc chỉ tồn tại trong tab hiện tại. Tải báo cáo trước khi tải lại hoặc đóng trang.</p></section></div>`;}
function render(){
 const focus=document.activeElement?.id,start=document.activeElement?.selectionStart;
 navigation();$('#main').innerHTML=({overview,events:eventsView,comparison:comparisonView,reports:reportsView,guide:guideView})[state.view]();
 if(focus){const field=document.getElementById(focus);if(field){field.focus();if(start!==null&&field.setSelectionRange)try{field.setSelectionRange(start,start);}catch{}}}
}
function openDrawer(content,footer=''){const previous=document.activeElement;$('#drawer-root').innerHTML=`<div class="drawer-overlay" data-overlay="drawer"><section class="drawer" role="dialog" aria-modal="true" aria-label="Chi tiết event" tabindex="-1">${content}${footer?`<div class="drawer-footer">${footer}</div>`:''}</section></div>`;document.body.style.overflow='hidden';$('#drawer-root .drawer').focus();state.returnFocus=previous;}
function closeDrawer(){$('#drawer-root').innerHTML='';document.body.style.overflow='';state.selected=null;state.returnFocus?.focus();}
function drawerHeader(title,description,top=''){return`<div class="drawer-header"><div>${top}<h2>${h(title)}</h2><p>${h(description)}</p></div><button class="icon-button" data-action="close-drawer" aria-label="Đóng chi tiết">${icon('close')}</button></div>`;}
function showEvent(id){const e=state.events.find(x=>x.id===id);if(!e)return;state.selected=e;openDrawer(drawerHeader(e.name,e.id,vendorTag(e.vendor))+`<div class="drawer-content"><div class="detail-grid">${[['Thời gian',time(e.time)],['HTTP status',e.status||'Không có phản hồi'],['Method',e.method],['Thời gian request',`${e.duration.toFixed(0)} ms`],['Nguồn bằng chứng',e.file],['Lớp quan sát','TRACKING_REQUEST']].map(([label,value])=>`<div><span class="label">${label}</span><div class="detail-value">${h(value)}</div></div>`).join('')}</div><span class="label">ENDPOINT</span><div class="detail-value mono">${h(e.url)}</div><div class="spacer"></div><span class="label">TRANG PHÁT SINH</span><div class="detail-value">${h(e.page||'HAR không cung cấp URL trang.')}</div>${e.issues.length?`<div class="notice warning">${e.issues.map(x=>`<div>• ${h(x.message)}</div>`).join('')}</div>`:''}<div class="spacer"></div><div class="section-header"><h2>Payload đã giải mã</h2><span class="tag">${e.decoded?'DECODED':'UNPARSED'}</span></div><pre class="payload">${h(JSON.stringify(e.payload,null,2))}</pre><div class="notice">Request headers và cookies không được lưu trong event. Một số trường nhạy cảm đã được che.</div></div>`,`<button class="button" data-action="close-drawer">Đóng</button><button class="button primary" data-action="copy-payload">${icon('copy')} Sao chép JSON</button>`);}
function showComparison(id){const r=state.rows.find(x=>x.id===id);if(!r)return;openDrawer(drawerHeader(r.name,`${r.spec?.provenance?.file??'Ngoài đặc tả'}${r.spec?' · dòng '+r.spec.provenance.row:''}`,badge(r.status))+`<div class="drawer-content"><div class="detail-grid"><div><span class="label">Nền tảng</span>${vendorTag(r.vendor)}</div><div><span class="label">Luồng</span><div class="detail-value">${h(r.flow||'Chưa chỉ định')}</div></div><div><span class="label">Event đã thấy</span><div class="detail-value">${r.matches}</div></div><div><span class="label">Loại đối chiếu</span><div class="detail-value">${r.inferred?'Cấu trúc từ sample':'Rule chỉ định trong JSON'}</div></div></div>${r.spec?.description?`<span class="label">Điều kiện nghiệp vụ cần xác nhận</span><p class="detail-value">${h(r.spec.description)}</p>`:''}${r.issues.length?`<div class="notice ${r.status==='FAIL'?'error':'warning'}">${r.issues.map(x=>`<div>• ${h(x)}</div>`).join('')}</div>`:''}${r.checks.length?`<div class="section-header"><h2>Kiểm tra từng trường</h2><span class="tag">${num(r.checks.length)} PHÉP KIỂM</span></div><ul class="check-list">${r.checks.slice(0,250).map(c=>`<li>${badge(c.status)}<div><div class="check-path">${h(c.path)}</div><div class="check-values">Kỳ vọng: ${h(c.expected)}<br>Thực tế: ${h(typeof c.actual==='object'?JSON.stringify(c.actual):c.actual)}<br>Evidence: ${h(c.eventId)}</div></div></li>`).join('')}</ul>${r.checks.length>250?'<p class="detail-value">Hiển thị 250 phép kiểm đầu. Báo cáo JSON có toàn bộ kết quả.</p>':''}`:''}<div class="spacer"></div><div class="section-header"><h2>Event bằng chứng</h2></div>${r.eventIds.slice(0,40).map(eventId=>`<div style="margin-bottom:7px"><button class="button small" data-event="${h(eventId)}">${icon('eye')} ${h(eventId)}</button></div>`).join('')||'<p class="detail-value">Chưa có event bằng chứng trong HAR.</p>'}</div>`,`<button class="button" data-action="close-drawer">Đóng</button><button class="button primary" data-view="reports">${icon('download')} Xuất báo cáo</button>`);}
function confirmReset(){if(!state.events.length&&!state.specs.length){reset();return;}$('#modal-root').innerHTML=`<div class="modal-overlay" data-overlay="modal"><section class="modal" role="dialog" aria-modal="true" aria-label="Xóa phiên"><h2>Xóa phiên kiểm thử?</h2><p>File đã nhập và kết quả hiện tại sẽ bị xóa khỏi tab này. Hãy tải báo cáo nếu bạn cần giữ lại.</p><div class="modal-actions"><button class="button" data-action="close-modal">Giữ phiên</button><button class="button primary" data-action="confirm-reset">Xóa phiên</button></div></section></div>`;$('#modal-root button').focus();}
function reset(){Object.assign(state,{files:[],events:[],specs:[],specFile:'',specWarnings:[],workbook:null,sheet:'',rows:[],demo:false,busy:false,analyzed:false,search:'',vendor:'ALL',eventFilter:'ALL',resultFilter:'ALL',page:1});$('#modal-root').innerHTML='';closeDrawer();navigate('overview');toast('Đã xóa dữ liệu phiên hiện tại.');}
function loadDemo(){const{har,specs}=demoData();const parsed=parseHar(har,'demo-tracking.har'),spec=specFromJSON(specs,'demo-rules.json');Object.assign(state,{files:[{name:'demo-tracking.har',...parsed}],specs:spec.specs,specFile:'demo-rules.json',specWarnings:[],workbook:null,sheet:'',analyzed:true,demo:true,resultFilter:'ALL',eventFilter:'ALL'});refreshData();navigate('overview');toast('Đã nạp dữ liệu minh họa. Bạn có thể thử xem và xuất báo cáo.');}
async function importHAR(files){
 if(!files.length)return;if(state.busy)return;state.busy=true;render();await new Promise(r=>setTimeout(r,30));
 const errors=[];
 for(const file of files){try{if(file.size>60*1024*1024)throw new Error('File lớn hơn 60 MB. Hãy ghi HAR ngắn hơn.');const data=JSON.parse(await file.text());const validated=parseHar(data,file.name);if(state.demo){state.files=[];state.specs=[];state.specFile='';state.demo=false;state.workbook=null;state.sheet='';state.analyzed=false;}
 let name=file.name;let suffix=2;while(state.files.some(x=>x.name===name))name=file.name.replace(/(\.[^.]+)?$/,` (${suffix++})$1`);const parsed=name===file.name?validated:parseHar(data,name);state.files.push({name,size:file.size,...parsed});}catch(e){errors.push(`${file.name}: ${e.message}`);}}
 state.busy=false;state.analyzed=false;refreshData();render();if(errors.length)showMessage('Một số file chưa đọc được',errors);else toast(`Đã đọc ${num(state.events.length)} event tracking. Bấm Bắt đầu kiểm tra để tiếp tục.`);
}
async function importSpec(file){if(!file||state.busy)return;state.busy=true;render();await new Promise(r=>setTimeout(r,30));try{if(file.size>20*1024*1024)throw new Error('File đặc tả lớn hơn 20 MB. Hãy xuất riêng sheet cần kiểm tra.');const ext=file.name.split('.').pop().toLowerCase();let result,wb=null,sheet='';
 if(ext==='xlsx'){wb=await readXLSX(await file.arrayBuffer());sheet=wb.names.find(n=>n==='Tổng hợp Event tracking')??wb.names[0];result=specFromRows(await wb.rows(sheet),file.name,sheet);}else if(ext==='csv')result=specFromRows(parseCSV(await file.text()),file.name);else if(ext==='json')result=specFromJSON(JSON.parse(await file.text()),file.name);else throw new Error('Chỉ hỗ trợ .xlsx, .csv và .json.');
 if(state.demo){state.files=[];state.events=[];}Object.assign(state,{specs:result.specs,specFile:file.name,specWarnings:result.warnings,workbook:wb,sheet,analyzed:false,demo:false});state.rows=[];toast(`Đã nhập ${num(result.specs.length)} dòng đặc tả.`);
 }catch(e){showMessage('Chưa đọc được đặc tả',[e.message,'Bạn có thể xuất sheet đặc tả thành CSV hoặc dùng JSON rule mẫu ở Hướng dẫn.']);}finally{state.busy=false;render();}}
function analyze(){if(!state.events.length)return;state.analyzed=true;refreshData();navigate(state.specs.length?'comparison':'events');toast(state.specs.length?'Đã đối chiếu event với đặc tả.':'Đã đọc event. Thêm đặc tả để đối chiếu.');}
function showMessage(title,lines){$('#modal-root').innerHTML=`<div class="modal-overlay" data-overlay="modal"><section class="modal" role="dialog" aria-modal="true"><h2>${h(title)}</h2>${lines.map(x=>`<p>${h(x)}</p>`).join('')}<div class="modal-actions"><button class="button primary" data-action="close-modal">Đã hiểu</button></div></section></div>`;$('#modal-root button').focus();}
function save(name,data,type='text/plain;charset=utf-8'){const blob=data instanceof Blob?data:new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast(`Đã tạo ${name}`);}
const eventRows=()=>[['Event Name','Vendor','Time','HTTP','Method','Endpoint','Page','Evidence ID','Payload','Warnings'],...state.events.map(e=>[e.name,e.vendor,e.time,e.status,e.method,e.endpoint,e.page,e.id,JSON.stringify(e.payload),e.issues.map(x=>x.message).join(' | ')])];
const resultRows=()=>[['Event Name','Vendor','Flow','Result','Observed Count','Spec File','Spec Row','Issues','Evidence IDs'],...state.rows.map(r=>[r.name,r.vendor,r.flow,labels[r.status],r.matches,r.spec?.provenance?.file??'',r.spec?.provenance?.row??'',r.issues.join(' | '),r.eventIds.join(' | ')])];
function summaryRows(){return[['Chỉ số','Giá trị'],['Phiên bản',VERSION],['Tạo lúc',new Date().toISOString()],['Dữ liệu mẫu',state.demo?'Có':'Không'],['HAR',state.files.map(f=>f.name).join(', ')],['Đặc tả',state.specFile||'Chưa có'],['Tổng event',state.events.length],['Đã đối chiếu',state.analyzed?'Có':'Chưa'],...Object.entries(labels).filter(([k])=>k!=='IGNORE').map(([key,label])=>[label,state.rows.filter(r=>r.status===key).length]),['Phạm vi','Tracking requests trong HAR; không quan sát JS queue hay xác nhận vendor ingestion.'],['Sample Excel','Chỉ kiểm tra kiểu và sự hiện diện; giá trị ví dụ không tự là giá trị bắt buộc.']];}
function htmlReport(){return`<!doctype html><html lang="vi"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Event QA Report</title><style>body{font:14px/1.7 Arial,sans-serif;color:#233149;margin:40px auto;padding:0 24px;max-width:1200px}h1{font-size:30px}table{border-collapse:collapse;width:100%;font-size:12px;margin-bottom:30px}th,td{padding:10px;text-align:left;border:1px solid #e3e8f0;vertical-align:top;word-break:break-word}th{background:#17243f;color:white}pre{white-space:pre-wrap;word-break:break-word;background:#f5f7fb;padding:16px}summary{cursor:pointer;padding:10px;background:#f5f7fb}details{margin-bottom:10px}small{color:#8190a8}.FAIL{color:#bf4c58}.PASS{color:#23846a}</style><h1>Event Tracking QA · Báo cáo</h1><small>${h(new Date().toLocaleString('vi-VN'))}${state.demo?' · DỮ LIỆU MINH HỌA':''}</small><p>Phạm vi: request trong HAR. HTTP 200 không xác nhận vendor ingestion. Chưa thấy event không tự động là lỗi.</p><h2>Tổng quan</h2><table>${summaryRows().map((row,i)=>`<tr>${row.map(v=>`<${i?'td':'th'}>${h(v)}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</table><h2>Đối chiếu</h2><table><tr><th>Event</th><th>Nền tảng</th><th>Kết quả</th><th>Ghi chú</th></tr>${state.rows.map(r=>`<tr><td>${h(r.name)}</td><td>${h(r.vendor)}</td><td class="${r.status}">${h(labels[r.status])}</td><td>${h(r.issues.join(' | '))}</td></tr>`).join('')}</table><h2>Event bằng chứng</h2>${state.events.map(e=>`<details><summary>${h(e.name)} · ${h(e.vendor)} · HTTP ${e.status} · ${h(e.id)}</summary><p>${h(e.url)}</p><pre>${h(JSON.stringify(e.payload,null,2))}</pre></details>`).join('')}</html>`;}
function exportFile(format){
 const date=new Date().toISOString().slice(0,10),prefix=`event-qa-${state.demo?'demo-':''}${date}`;
 if(format==='template-json'){save('event-qa-rules-example.json',JSON.stringify(demoData().specs,null,2),'application/json');return;}
 if(format==='template-xlsx'){save('event-qa-spec-template.xlsx',writeXLSX({'Tổng hợp Event tracking':[['STT','Nền tảng','Luồng','Event Name','Event Description','DataLayer Sample','Note'],[1,'GA4','Hotel','search_submit','Khi thực hiện tìm kiếm khách sạn',JSON.stringify({event:'search_submit',service:'hotel',search_term:'Da Nang',destination_id:123},null,2),'Giá trị chỉ là ví dụ.'],[2,'Insider','Golf','listing_page_view','Khi mở danh sách Golf',JSON.stringify({event_name:'listing_page_view',event_params:{custom:{service:'golf',item_count:12}}},null,2),'']]}));return;}
 if(!state.events.length){toast('Nhập HAR trước khi xuất báo cáo.');return;}
 if(format==='events-csv')save(prefix+'-events.csv',csv(eventRows()),'text/csv;charset=utf-8');
 if(format==='results-csv')save(prefix+'-comparison.csv',csv(resultRows()),'text/csv;charset=utf-8');
 if(format==='json')save(prefix+'.json',JSON.stringify(reportData(state.events,state.rows,{demo:state.demo,analyzed:state.analyzed,files:state.files.map(f=>f.name),spec_file:state.specFile}),null,2),'application/json');
 if(format==='bugs')save(prefix+'-bugs.md',bugMarkdown(state.rows));
 if(format==='html')save(prefix+'.html',htmlReport(),'text/html;charset=utf-8');
 if(format==='xlsx')save(prefix+'.xlsx',writeXLSX({'Run Summary':summaryRows(),'Actual Events':eventRows(),'Comparison':resultRows(),'Bugs':[['Event','Vendor','Flow','Issue','Evidence ID'],...state.rows.filter(r=>r.status==='FAIL').flatMap(r=>r.issues.map(issue=>[r.name,r.vendor,r.flow,issue,r.eventIds.join(' | ')]))]}));
}
document.addEventListener('click',async event=>{
 if(event.target.closest('a.brand')){event.preventDefault();navigate('overview');return;}
 const target=event.target.closest('[data-view],[data-action],[data-event],[data-comparison],[data-export],[data-remove],[data-drop],[data-page],[data-event-filter],[data-result-filter]');
 if(!target){if(event.target.matches('[data-overlay="drawer"]'))closeDrawer();if(event.target.matches('[data-overlay="modal"]'))$('#modal-root').innerHTML='';return;}
 if(target.disabled)return;
 if(target.dataset.view){closeDrawer();navigate(target.dataset.view);return;}
 if(target.dataset.event){showEvent(target.dataset.event);return;}
 if(target.dataset.comparison){showComparison(target.dataset.comparison);return;}
 if(target.dataset.export){exportFile(target.dataset.export);return;}
 if(target.dataset.drop){$(`#${target.dataset.drop}-input`).click();return;}
 if(target.hasAttribute('data-remove')){state.files.splice(Number(target.dataset.remove),1);refreshData();render();return;}
 if(target.dataset.page){state.page=Number(target.dataset.page);render();return;}
 if(target.dataset.eventFilter){state.eventFilter=target.dataset.eventFilter;state.page=1;render();return;}
 if(target.dataset.resultFilter){state.resultFilter=target.dataset.resultFilter;state.page=1;render();return;}
 switch(target.dataset.action){case'demo':if(state.events.length&&!state.demo)showMessage('Phiên hiện tại có dữ liệu',['Hãy xuất báo cáo và xóa phiên trước khi nạp dữ liệu mẫu.']);else loadDemo();break;case'analyze':analyze();break;case'import-har':$('#har-input').click();break;case'close-drawer':closeDrawer();break;case'close-modal':$('#modal-root').innerHTML='';break;case'reset':confirmReset();break;case'confirm-reset':reset();break;case'remove-spec':Object.assign(state,{specs:[],specFile:'',workbook:null,sheet:'',specWarnings:[],analyzed:false,rows:[]});render();break;case'warnings':showMessage('Lưu ý khi đọc dữ liệu',[...state.specWarnings,...state.files.flatMap(f=>f.warnings)]);break;case'copy-payload':try{await navigator.clipboard.writeText(JSON.stringify(state.selected?.payload??{},null,2));toast('Đã sao chép payload.');}catch{toast('Trình duyệt chặn clipboard. Bạn có thể chọn nội dung JSON để sao chép.');}break;}
});
document.addEventListener('input',event=>{if(event.target.id==='table-search'){state.search=event.target.value;state.page=1;render();}});
document.addEventListener('change',async event=>{
 if(event.target.id==='har-input'){await importHAR([...event.target.files]);event.target.value='';}
 if(event.target.id==='spec-input'){await importSpec(event.target.files[0]);event.target.value='';}
 if(event.target.id==='vendor-filter'){state.vendor=event.target.value;state.page=1;render();}
 if(event.target.id==='sheet-select'){try{const sheet=event.target.value,result=specFromRows(await state.workbook.rows(sheet),state.specFile,sheet);Object.assign(state,{sheet,specs:result.specs,specWarnings:result.warnings,analyzed:false,rows:[]});render();}catch(e){showMessage('Sheet chưa phù hợp',[e.message]);render();}}
});
document.addEventListener('dragover',event=>{const zone=event.target.closest('[data-drop]');if(zone){event.preventDefault();zone.classList.add('dragging');}});
document.addEventListener('dragleave',event=>{const zone=event.target.closest('[data-drop]');if(zone&&!zone.contains(event.relatedTarget))zone.classList.remove('dragging');});
document.addEventListener('drop',async event=>{const zone=event.target.closest('[data-drop]');if(zone){event.preventDefault();zone.classList.remove('dragging');if(zone.dataset.drop==='har')await importHAR([...event.dataTransfer.files]);else await importSpec(event.dataTransfer.files[0]);}});
document.addEventListener('keydown',event=>{
 if(event.key==='Escape'){if($('#modal-root').firstChild)$('#modal-root').innerHTML='';else closeDrawer();}
 if((event.key==='Enter'||event.key===' ')&&event.target.matches('[data-drop],tr[data-event],tr[data-comparison]')){event.preventDefault();event.target.click();}
 if(event.key==='Tab'){const modal=$('#modal-root [role="dialog"]')??$('#drawer-root [role="dialog"]');if(modal){const elements=[...modal.querySelectorAll('button:not([disabled]),a[href],input,select,[tabindex="0"]')];if(elements.length){if(event.shiftKey&&document.activeElement===elements[0]){event.preventDefault();elements.at(-1).focus();}else if(!event.shiftKey&&document.activeElement===elements.at(-1)){event.preventDefault();elements[0].focus();}}}}
});
$('#guide-top').addEventListener('click',()=>navigate('guide'));
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
state.view=views[location.hash.slice(1)]?location.hash.slice(1):'overview';render();
